/* 本美化免费发布于🍠抹茶，不准倒卖二传等一切商业化行为！ */
/* 二改作者：苦等14世纪的冬雪 */
/* 部分图源 xhs 卷毛媛，素材来自 xhs/花瓣分享，侵权可删 */
/* 部分代码参考源 @旅程美化教程贴的老师们 */
/*感谢抹茶老婆的产出！表白抹茶 已获得授权二改发布到社区*/
/* 字体 */

/* UI背景图 只显示一张原图、不重复、不拉伸、居中完整显示 */
.drawer-content {
    /* 背景图片地址 */
    background-image: url('https://s3.bmp.ovh/2026/04/01/Hx2cUfNr.png');
    /* 完整显示整张图，不拉伸不变形 */
    background-size: cover;
    background-repeat: no-repeat;
    /* 图片在容器里居中 */
    background-position: center;
}

/*气泡本体 */
.mes {
  background: none;
  background-image: url('https://s3.bmp.ovh/2026/04/01/MMPC0Ke9.png');
  background-position: center center;
  background-repeat: repeat-y;
  background-size: contain;
  background-attachment: scroll;
  box-shadow: 0 0 0px rgba(238, 151, 169, 0.8);
}

.mes {
    --bubble-width: 100%;  
    --vertical-spacing: 2rem; 
    margin: var(--vertical-spacing) auto !important; 
}

/* ai文本 */
.mes[is_user="false"] .mes_text {
    padding: 250px 10px 63px 1px !important;
    letter-spacing: -0.5px;
    color: #505D72 !important;
}

/* 用户文本 */
.mes[is_user="true"] .mes_text {
    padding: 250px 10px 50px 1px !important; 
    letter-spacing: -0.5px;
    color: #505D72 !important;
}

.mes_text {
    line-height: 2.1; 
    color: #505D72 !important;
}
/*底层图片 */
.mes::after {
    content: "";
    position: absolute;
    bottom: -10px;/*上下位置，显示不完整调这个🍓 */
    left: 0;
    right: 0px;
    height: 195px;/*图片高度，显示不完整调这个🍓 */
    background: 
        linear-gradient(
            to top, 
            rgba(255, 255, 255, 0) 0%, 
            rgba(255, 255, 255, 0) 50%, 
            rgba(255, 255, 255, 0) 80%, 
            rgba(255, 255, 255, 0) 100%
        ),
        url('https://i.postimg.cc/Vv80ssK0/wu-biao-ti163-20260401195113.png') center / cover no-repeat; 
    z-index: 1;
}

/*顶层图片 */
.mes::before {
    content: "";
    position: absolute;
    top: 0px;/*上下位置，显示不完整调这个🍓 */
    left: 0;
    right: 0;
    height: 450px; /*图片高度，显示不完整调这个🍓 */
    background: 
        linear-gradient(
            to bottom, 
            rgba(255, 255, 255, 0) 0%, 
            rgba(255, 255, 255, 0) 50%, 
            rgba(255, 255, 255, 0) 80%, 
            rgba(255, 255, 255, 0) 100%
        ),
        url('https://s3.bmp.ovh/2026/04/01/uA9JWCMX.png') center / cover no-repeat;
    border-radius: 0px 0px 0 0;
    z-index: 1;
}
.swipes-counter {
  position: absolute;
  top: -30px;
  right: 10px;
  z-index: 999;
  pointer-events: none;
}
.swipes-counter {
  font-size: 10px;
  opacity: 1 !important;
  color: #505D72 !important;
  white-space: nowrap !important;
}
/*滑块图标 */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
    appearance: none;
    width: 30px;
    height: 30px;
    background: transparent url('https://s3.bmp.ovh/2026/04/01/17oIh7xQ.png') center/cover no-repeat;
    border: none;
    border-radius: 0;
    box-shadow: none;
    cursor: ew-resize;
    position: relative;
    z-index: 1;
}

input[type="range"] {
    background: #505D72 !important;
    box-shadow: 0 0px 0px rgba(155,172,141,0.4) !important; 
    border: 1px solid #fff !important;
    padding: 2px 1px 0px 1px !important;
    height: 0px; 
}

input:not([type="file" i], [type="image" i], [type="checkbox" i], [type="radio" i]) {
  background-color: #F2F5F8;
  box-shadow: 2px 2px 0px rgba(203, 217, 224, 1);
  border-radius: 0px 0x 0px 0px;
  padding: 2px 1px;
  border: 1.5px solid #505D72;
  color: #505D72;
  outline: none;
}

/*拓展键 */
.fa-bars {
  background: url('https://s3.bmp.ovh/2026/04/01/tLI1VFB3.png') center/contain no-repeat !important;
  width: 30px !important;
  height: 30px !important;
  margin-top: 2px !important;
  opacity: 1 !important
}

/*菜单键 */
#extensionsMenuButton {
  background: url('https://s3.bmp.ovh/2026/04/01/tLI1VFB3.png') center/contain no-repeat !important;
  width:30px !important;
  height: 30px !important;
  margin-top: 2px !important;
opacity: 1 !important
}

/* 发送键 */
.fa-paper-plane {
  background: url('https://s3.bmp.ovh/2026/04/01/tLI1VFB3.png') center/contain no-repeat !important;
  width: 30px !important;
  height: 30px !important;
  margin-top: 2px !important;
  opacity: 1 !important
}

/* 暂停键 */
.fa-circle-stop::before {
  color: #F2F5F8;
  font-size: 1em;
  opacity: 1 !important;
}


/* 头像位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: 30px !important; 
    left: 50% !important; 
    transform: translateX(-50%) !important;
    z-index: 2 !important;
    margin: 0 !important;
}
/* 头像大小 */
.mesAvatarWrapper .avatar {
  width: 150px !important;
  height: 150px !important;
  border-radius: 50% !important;
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  display: block !important;
}

.mesAvatarWrapper .avatar img {
    -webkit-mask-image: url('https://i.postimg.cc/HsV4PgJZ/IMG-2094.png');
  mask-image: url('https://i.postimg.cc/HsV4PgJZ/IMG-2094.png');
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
}

/* 头像框 */
.mesAvatarWrapper::before {
  content: "";
  position: absolute;
  background-image: url('https://i.postimg.cc/13xRBBdN/wu-biao-ti162-20260401153509.png');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  width: 380px;
  height: 380px;
  top: -23px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 3;
  pointer-events: none;
}

.mesAvatarWrapper .avatar,
.mesAvatarWrapper .avatar img,
.mesAvatarWrapper .avatar::before,
.mesAvatarWrapper .avatar::after {
  box-shadow: none !important;
  filter: none !important; 
  text-shadow: none !important; /* 移除文字阴影*/
}

/* 时间戳 */
.timestamp {
    position: absolute !important;
    top: -35px !important;
    right: 213px !important;
    color: #7A8496 !important;
    font-size: 11px !important;
    z-index: 999 !important;
}

.timestamp::before {
    content: "" !important;
    margin-right: 0px;
  color: #7A8496;
  display: inline !important; /* 改为inline使其与名字在同一行 */
  vertical-align: middle;
  position: relative;
  top: -1px;
}

.mes_block {
    position: relative;
    z-index: 999 !important; 
    isolation: isolate; 
}

/* 名字位置 */
.mes_block .ch_name {
  position: relative;
  top:240px;
  left: 4px;
  max-width: calc(100% - 105px); 
  min-height: 0px;
  z-index: 5; 
  letter-spacing: 0px;
  white-space: nowrap;
  color: #7A8496 !important;
  font-size: 0.9em;
  font-weight: 100!important;
  white-space: nowrap !important;
  z-index: 999 !important;
}

/* 添加后缀 */
.mes_block .ch_name::after {
  content: ""; /* 后缀文本 */
  margin-left: 20px;
  color: #7A8496;
  display: inline !important; /* 改为inline使其与名字在同一行 */
  vertical-align: middle;
  position: relative;
  top: -1px;
  left: -80px !important;
}


/* 楼层 */
.mesIDDisplay {
    position: absolute !important;
    top: 183px !important;
    left: 60px !important;
    display: flex !important;
    font-size: 0.85em!important;
    z-index: 888 !important;
    color: #7A8496 !important;
    font-weight: 300 !important;
    white-space: nowrap !important;
}

.mesIDDisplay::before {
    content: "♡";
    margin-right: 0px;
    color: #7A8496;
    display: flex !important;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
}


/* 计时器 */
.mes .mes_timer {
    position: absolute !important;
    top: 183px !important;  
    left: 160px !important;  
    display: flex !important;
    font-size: 0.85em;
    z-index: 888 !important;
    font-weight: 300;
    color: #7A8496 !important;
    white-space: nowrap !important;
}

.mes .mes_timer::before {
    content: "♡";
    margin-right: 0px;
    color: #7A8496;
    display: inline-block;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
}

.mes .tokenCounterDisplay {
    position: absolute !important;
    top: 183px !important;
    left: 110px !important;  
    display: flex !important;
    font-size: 0.85em;
    z-index: 888 !important;
    opacity: 1;
    color: #7A8496 !important;
font-weight: 300;
}

.mes .tokenCounterDisplay::before {
    content: "♡";
    margin-right: 0px;
    color: #7A8496;
    display: inline-block;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
    white-space: nowrap !important;
}


/* 编辑按钮位置 */
.mes_buttons {
    position: absolute !important;
    top: -40px !important;
    right: -105px !important;
    z-index: 999 !important;
    flex-direction: row !important; 
}

/* 编辑状态时按钮位置 */
.mes_edit_buttons {
    position: relative !important;
    top: -20px !important;
    left: 20px !important;
    margin-bottom: -20px !important;
    z-index: 100 !important;
}

/* --- 编辑的省略号图标 --- */
.fa-ellipsis-h, 
.fa-ellipsis {
    background: url('https://i.postimg.cc/WbRYNYf4/wu-biao-ti155-20260401171851.png') center/contain no-repeat !important;
    width: 24px !important;   
    height: 24px !important;  
    color: transparent !important; 
z-index: 999 !important;
    opacity: 1 !important
}

/* --- 替换编辑图标 --- */
.fa-pencil-alt, 
.fa-pencil {
    background: url('https://i.postimg.cc/WbRYNYf4/wu-biao-ti155-20260401171851.png') center/contain no-repeat !important;
    width: 24px !important;
    height: 24px !important;
    color: transparent !important;
z-index: 999 !important;
    opacity: 1 !important
}


/* 导航栏 */
#top-bar::after {
    content: "";
    position: fixed;
    top: var(--topBar-height, -16px); 
    left: 0px;
    width: 100%;
    height: 50px;
    background: url('https://i.postimg.cc/mDwBMbbL/wu-biao-ti163-20260401193351.png') center/cover no-repeat;
    z-index: 999;
}

 /*小风铃 */
#top-bar::before {
    content: "";
    position: fixed;
    top: calc(var(--topBar-height, -15px) + 40px); 
    left: 355px;
    width: 10%;
    height: 90px; 
    background: url('https://i.postimg.cc/J0MgNJTL/wu-biao-ti164-20260401204649.png') center/cover no-repeat;
    z-index: 999;
    /* 关键：旋转轴设在顶部，只有下半部分会摆 */
    animation: swing 2.5s ease-in-out infinite;
    transform-origin: top center;
}

@keyframes swing {
    0%  { transform: rotate(-7deg); }
    50% { transform: rotate(7deg); }
    100%{ transform: rotate(-7deg); }
}

/* 隐藏原有图标 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden; 
}

/* 图标容器 - 负责点击 */
#top-settings-holder .drawer-icon {
    opacity: 1 !important;
    pointer-events: auto !important;
    position: relative !important;
    z-index: 5 !important;
    display: inline-block !important;
    width: 23px !important;                 /* 【自定义点击区域宽度】已调小至 20px */
    height: 23px !important;                /* 【自定义点击区域高度】已调小至 20px */
    background: transparent !important;
}

#top-settings-holder .drawer {
    flex: 1; 

}

/* 预设 */
/* 背景 */
#completion_prompt_manager #completion_prompt_manager_list {
  background-color: rgba(255, 255, 255, 0.3) !important;
  border-radius: 0px !important;
  box-shadow: 0 0px 0px rgba(245, 166, 184, 0.7) !important;
  padding: 12px !important;
  transition: all 0.3s ease !important; 
  border: 0px solid rgba(245, 197, 220, 0.2) !important; 
  position: relative !important;
  overflow: hidden !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: #505D72 !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background-color: #F2F5F8 !important; 
  color: #505D72 !important; 
  box-shadow: 0px 0px 0px rgba(245, 166, 184, 0.9) !important; 
  border: 1.5px solid #505D72;
outline: 1.5px solid #505D72 !important; 
  border-radius: 0px !important; 
  padding: 1px 1px !important; 
  margin: 5px 5px !important; 
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background-color: #fff !important; 
  color: #505D72 !important; 
  box-shadow: 0px 2px 4px rgba(245, 197, 220, 0.4) !important;
  border: 1.5px solid #505D72;
outline: 1.5px solid #505D72 !important; 
  border-radius: 0px !important;
  margin: 8px 5px !important;
  opacity: 1 !important; 
}

/* 条目已开启颜色 代码源@hy */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .fa-toggle-on {
    color: #505D72 !important; 
    text-shadow: 0 0 0px rgba(0, 0, 0, 1) !important;
opacity: 1 !important;
}

/*菜单按钮*/
.menu_button {
  background-color: #F2F5F8!important; 
  box-shadow: 2px 2px 0px rgba(203, 217, 224, 1);
  border: 1.5px solid #505D72 !important; 
  border-radius: 1px !important; 
  padding: 1px 4px !important; 
  color: #505D72 !important;
  opacity: 1 !important
}

/* 代码块 */
code, .hljs {
  position: relative;
  background-color: #F2F5F8 !important;
  border-radius: 1px !important;
  border: 1.5px solid #505D72;
  box-shadow: 2px 2px 0px rgba(203, 217, 224, 1);
   color: #505D72 !important;
}

/* 下拉框 */
select {
    background-size: 100%;
  background: #F2F5F8;
  color: #505D72 !important; 
  border: 1.5px solid #505D72 !important;
  background-position: center;
  box-shadow: 
    inset 0 0 0 0px #fff,
    0 0px 0px rgba(0, 0, 0, 0.9),
    inset 0 0 1px rgba(243, 246, 255, 1) !important;
  border-radius: 1px;
  transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  padding: 2px 4px !important;
  color: #505D72 !important;
  background-position: center;
  position: relative;
}

select, 
select option {
  color: #505D72 !important;
}

/* 勾选框 */
input[type='checkbox'] {
  background-color: #505D72 !important;
  border: 1px solid #F2F5F8 !important;
  border-radius: 1px !important;
  appearance: none !important; /* 移除默认样式 */
  -webkit-appearance: none !important;
  width: 13px !important;
  height: 13px !important;
  cursor: pointer !important;
  position: relative !important;
  transition: all 0.3s ease !important;
  top: 3px !important;
}

/* 选中 */
input[type='checkbox']:checked {
  background-color: #C2CBD8 !important;
  border-color: #505D72 !important;
}

/* 气泡内的勾选框 */
.mes input[type="checkbox"] {
    top: 155px !important;  
    left: 40px !important; 
    z-index: 9999 !important; 
    opacity: 1 !important;
    float: none !important;
    margin: 0 !important;
    pointer-events: auto !important; 

    width: 15px !important;
    height: 15px !important;
    background-color: #505D72 !important;
    border: 1.5px solid #505D72 !important; 
    border-radius: 1% !important; 
}

/* 选中时 */
.mes input[type="checkbox"]:checked {
    background-color: #C2CBD8 !important;
    border-color: #505D72 !important;
    box-shadow: 0 0 0px rgba(226, 198, 209, 1) !important;
}

.mes_select_box, .mes_checkbox {
    overflow: visible !important;
    z-index: 9999 !important;
}

/* 标题 */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background-size: 100%;
  overflow: visible !important;
  background-image: url("https://s3.bmp.ovh/2026/04/01/XXIXSjHZ.jpg");
  border: 1px dashed #ECE9F4 !important; /* 补全了border的数值1px，避免不生效 */
  box-shadow: 
    inset 0 0 0 1px #fff,
    0 0px 0px rgba(0, 0, 0, 0.5),
    inset 0 0 0px rgba(243, 246, 255, 1) !important;
  border-radius: 1px;
  transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  position: relative;
  overflow: hidden;
  padding: 2px 15px !important;
  color: #505D72 !important; /* 已修改为目标颜色，加!important确保优先级 */
}

/*输入文本框*/
textarea {
  background-color: #fff !important;
  box-shadow: inset 0px 0px 0px rgba(255, 123, 151, 0.6) !important;
  border: 1.5px solid #505D72!important;
  border-radius: 1px !important; 
  color: #505D72 !important; 
}
/*文本选中时颜色*/
::selection {
  background-color: #D1D8E2;
  color: #2A3447;
}

/* 输入框自定义文案 源@墨千尾 */
#nonQRFormItems {
    position: relative;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "날 기억하시겠어요?";
    color: #7A8496; 
    position: absolute; 
    top: 50%; 
    left: 50%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.5em; 
    pointer-events: none; 
    z-index: 10; 
    white-space: nowrap; 
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px); 
}

/*分割线 源@hy */
hr {
    height: 85px !important;
    background-image: url(' https://s3.bmp.ovh/2026/04/02/qnyrdtcO.png') !important; 
    background-repeat: no-repeat !important; 
    background-position: center !important;  
    background-size: contain !important;     
    border: none !important;
    box-shadow: none !important;  
    margin: 5px 0 !important;               
    background-color: transparent !important;
   opacity: 1 !important;
}

/* 思维链 */
.mes_reasoning_header {
    background-color: #F8F8F8 !important; 
    box-shadow: 0 0px 1px rgba(0, 0, 0, 0.1) !important;
    border-radius: 1px !important;
    left:  0% !important;
    top: 195px !important;
    padding: 0px 2px  !important; 
}
.mes_reasoning_header_title {
  font-size: 0; 
  color: transparent; 
}
.mes_reasoning_arrow {
    display: none !important;
}

.mes_reasoning_header::before {
    content: "첫사랑의 맛 "; 
    color: #737A8A !important; 
    font-size: 9px !important;
    font-weight: bold !important;
    line-height: normal !important; 
    display: block !important;

}

.mes_reasoning {
    margin-top: 200px !important;
    margin-bottom: 15px !important;
    color: #737A8A !important;
    position: relative !important;
    top: 5px !important;
    background-color: #F8F8F8 !important;
    box-shadow: 2px 2px 0px #DCE0E5 !important;
    border-radius: 1px !important;
    padding: 8px 10px !important;
    border: 1.5px solid #9BA3B0 !important;
}

/* 角色卡与用户界面 · 图片背景版 */
.avatar-container {
  background: url('https://s3.bmp.ovh/2026/04/02/6Aq2c9qO.png') center/cover no-repeat #F8F8F8 !important;
  color: #505D72 !important;
  border-radius: 12px !important;
  padding: 4px 6px !important;
  border: 1px solid #D6E0F0 !important;
  margin: 6px 0 !important;
}

.character_select {
  background: url('https://s3.bmp.ovh/2026/04/02/6Aq2c9qO.png') center/cover no-repeat #F8F8F8 !important;
  color: #7A8496 !important;
  border-radius: 12px !important;
  padding: 4px 6px !important;
  border: 1px solid #D6E0F0 !important;
  margin: 6px 0 !important;
}

.avatar-container .avatar,
.character_select .avatar {
  border-radius: 50% !important;
}
.avatar-container .avatar img,
.character_select .avatar img {
  border-radius: 50% !important;
