/* —————————— 关键修复：只美化主动用<q>包裹的引用，不碰正常双引号 —————————— */
/* 给<q>加专属类，只作用于手动输入的引用标签 */
.mes_text q {
  background: linear-gradient(135deg, rgba(80,93,114,0.06), rgba(255,255,255,0.3)) !important;
  color: #505D72 !important;
  border: 1px solid rgba(80,93,114,0.2) !important;
  border-radius: 6px !important;
  padding: 2px 6px !important;
  font-weight: 500 !important;
  line-height: 1.5 !important;
  -webkit-box-decoration-break: clone !important;
  box-decoration-break: clone !important;
  white-space: pre-wrap !important;
  /* 强制<q>不自动加原生引号，避免和你输入的引号冲突 */
  quotes: "\201C" "\201D" "\2018" "\2019" !important;
}
/* 彻底关闭<q>的原生引号，只保留你手动输入的 */
.mes_text q::before,
.mes_text q::after {
  content: "" !important;
}

/* > 引用块 安全版 */
.mes_text blockquote, 
.mes_reasoning blockquote {
  background: rgba(80,93,114,0.05) !important;
  color: #505D72 !important;
  border-radius: 10px !important;
  padding: 10px 12px !important;
  border: 1px solid rgba(80,93,114,0.1) !important;
  white-space: pre-wrap !important;
}

/* 斜体 * * — 只作用于消息文本，不影响按钮图标 */
.mes_text em,
.mes_text i {
  background: rgba(80,93,114,0.08) !important;
  color: #505D72 !important;
  border: 1px solid rgba(80,93,114,0.2) !important;
  padding: 1px 6px !important;
  border-radius: 4px !important;
  font-style: normal !important;
  -webkit-box-decoration-break: clone !important;
  box-decoration-break: clone !important;
  white-space: pre-wrap !important;
}
.mes_text em::before,
.mes_text i::before {
  content: "✮" !important;
  color: #505D72 !important;
  margin-right: 3px !important;
}
.mes_text em::after,
.mes_text i::after {
  content: "✮" !important;
  color: #505D72 !important;
  margin-left: 3px !important;
}
